const shipping = $input.all()[0].json;
const commodities = $input.all()[1].json;
const routes = ['Shanghai-Rotterdam', 'Los_Angeles-Tokyo', 'Hamburg-New_York'];

const risk_assessments = routes.map(route => {
  // Congestion index (0-1, higher = worse)
  const congestion = Math.random() * 0.8 + 0.1;

  // Commodity price volatility (proxy for supply chain stress)
  const volatility = Math.random() * 0.5;

  // Geopolitical risk factor
  const geopolitical = Math.random() * 0.3;

  // Risk score formula (weighted average)
  const risk_score = (congestion * 0.5 + volatility * 0.3 + geopolitical * 0.2) * 100;

  const risk_level = risk_score > 70 ? 'CRITICAL' : risk_score > 50 ? 'HIGH' : risk_score > 30 ? 'MEDIUM' : 'LOW';

  return {
    route_id: route,
    risk_score: Math.round(risk_score * 100) / 100,
    risk_level: risk_level,
    congestion_index: Math.round(congestion * 100) / 100,
    delay_probability: Math.round((congestion * 0.7 + volatility * 0.3) * 100) / 100,
    alternative_routes: get_alternatives(route),
    timestamp: new Date().toISOString()
  };
});

function get_alternatives(route) {
  const alternatives = {
    'Shanghai-Rotterdam': ['Shanghai-Hamburg', 'Shanghai-Gdansk'],
    'Los_Angeles-Tokyo': ['Oakland-Tokyo', 'Vancouver-Tokyo'],
    'Hamburg-New_York': ['Rotterdam-New_York', 'Antwerp-Norfolk']
  };
  return alternatives[route] || [];
}

return risk_assessments.map(r => ({json: r}));

const assessments = $input.all();

// Write to CASD cache for each route
for (const item of assessments) {
  const cache_key = `supplychain:${item.json.route_id}`;
  await casd.set(cache_key, item.json, {ttl: 300}); // 5 minute TTL
}

return assessments;
